// `@earshot/evals/cassettes`: the eval cassettes for both LLM adapters, one cassette per script
// with one interaction per turn, in `@earshot/agent/testing`'s format. CI's eval runs give them to
// the extractor as its `fetch` (`createCassetteFetch`), so no turn reaches a provider and CI
// spends nothing. Generated by scripts/gen-cassettes.ts from the scripts' ground truth.
//
// A cassette answers only requests built from the script's session context (session.ts): the
// turn's transcript, `DEMO_SESSION_ENTITIES`, and the script's call time and time zone.
//
// A separate entry point from `@earshot/evals`, because the files hold about 0.6 MB of JSON.
import type { Cassette, CassetteFile } from "@earshot/agent/testing";
import type { LlmProvider } from "@earshot/core";
import anthropicCassettes from "../cassettes/anthropic.json" with { type: "json" };
import groqCassettes from "../cassettes/groq.json" with { type: "json" };

/** The committed eval cassettes, per provider (cassettes/<provider>.json). */
export const EVAL_CASSETTES: Readonly<Record<LlmProvider, CassetteFile>> = {
  anthropic: anthropicCassettes as unknown as CassetteFile,
  groq: groqCassettes as unknown as CassetteFile,
};

/** One script's cassette for one provider; throws for a script with none. */
export function evalCassette(provider: LlmProvider, scriptId: string): Cassette {
  const found = EVAL_CASSETTES[provider].cassettes[scriptId];
  if (!found) throw new RangeError(`no ${provider} eval cassette for ${scriptId}`);
  return found;
}
